parses.pst_cedar:
@owner("security")
permit(
  principal is User,
  action == Action::"view",
  resource is Photo
) when {
  resource.public
};

permit(
  principal in Group::"staff",
  action in [Action::"view"],
  resource is Photo in Album::"all"
) when {
  (if context has nested.key then context.nested.key like "a*\*" else [1, 2, 3].contains(2) && (!({x: 1}.x < (-1)))) && (!(decimal("1.0").lessThan(decimal("0.0")) || ip("192.0.2.1").isLoopback() || (datetime("2026-10-01T00:00:00Z").offset(duration("1h")) < datetime("2026-10-01T00:00:00Z"))))
};

@empty("")
@text("quote\" and \n")
permit(
  principal == User::"a\"\n雪",
  action in [],
  resource is Photo
);
